static const size_t th8_keyRoot_size = sizeof(th8_keyRoot_data);

/*
 *----------------------------------------------------------------------
 *
 * Th8_GetEmbeddedKeyRoot --
 *
 *	Return a pointer to the embedded root public key blob
 *	and its size in bytes.
 *
 * Why / How:
 *	The root key is the trust anchor for the Harpy signature
 *	chain.  It is compiled into the binary as a static byte
 *	array generated by mkkey.tcl so that no external file
 *	access is needed to verify signatures.
 *
 * Results:
 *	Pointer to the key blob (static storage).  *pnData is
 *	set to the blob size if pnData is non-NULL.
 *
 * Side effects:
 *	None.
 *
 *----------------------------------------------------------------------
 */

const unsigned char *
Th8_GetEmbeddedKeyRoot(size_t *pnData)
{
    if (pnData) *pnData = th8_keyRoot_size;
    return th8_keyRoot_data;
}

